public boolean updateJobInfo(
      String submissionId,
      Timestamp startTime,
      int driverCore,
      int driverMemoryMB,
      int executorInstances,
      String dagName,
      String taskName,
      String appName) {
    if (bypassLog) {
      return true;
    }

    return timerMetrics.record(
        () ->
            updateJobInfoImpl(
                submissionId,
                startTime,
                driverCore,
                driverMemoryMB,
                executorInstances,
                dagName,
                taskName,
                appName),
        DB_TIMER_METRIC_NAME,
        Tag.of(OPERATION_TAG, UPDATE_SPARK_APP_INFO_OPERATION));
  }

